config.script:
deviceName = self.getSibling("Device Name").props.text
devices = system.dataset.toPyDataSet(system.device.listDevices())
exists = False
for device in devices:
	if device["Name"] == deviceName:
		exists = True
		break

if not exists:
	system.device.addDevice(deviceName=deviceName, deviceType="ProgrammableSimulatorDevice", deviceProps={})
	system.perspective.openPopup(id="message", view="L5K/Message", params={"message":"Device '%s' added" % deviceName, "error":False}, title="Message")
else:
	system.perspective.openPopup(id="message", view="L5K/Message", params={"message":"Device '%s' already exists" % deviceName, "error":True}, title="Error")
